CREATE TABLE T (ID INTEGER PRIMARY KEY, NAME VARCHAR(50), AMOUNT DOUBLE PRECISION);
INSERT INTO T VALUES (1,'a',0.5),(2,'b',1.5),(3,'c',2.5),(4,'c',3.5);
WITH frame_r AS (SELECT * FROM T), __e_0 AS (SELECT __v FROM (VALUES ('a'), ('b'), ('c')) AS v(__v)), __a_0 AS (SELECT NAME AS __v FROM frame_r WHERE NAME IS NOT NULL) SELECT 0 AS __ix, NOT EXISTS (SELECT 1 FROM (SELECT __v, 1 AS __s FROM __e_0 UNION ALL SELECT __v, -1 AS __s FROM __a_0) AS d GROUP BY d.__v HAVING SUM(d.__s) <> 0) AS __verdict, (SELECT LISTAGG(__v, ', ') WITHIN GROUP (ORDER BY __v) FROM __e_0) AS __expected, (SELECT LISTAGG(__v, ', ') WITHIN GROUP (ORDER BY __v) FROM __a_0) AS __actual;
WITH frame_r AS (SELECT * FROM T), __e_0 AS (SELECT CAST(__v AS DOUBLE PRECISION) AS __v FROM (VALUES (0.5), (1.5), (2.5)) AS v(__v)), __a_0 AS (SELECT AMOUNT AS __v FROM frame_r WHERE AMOUNT IS NOT NULL AND ID < 4) SELECT 0 AS __ix, NOT EXISTS (SELECT 1 FROM (SELECT __v, 1 AS __s FROM __e_0 UNION ALL SELECT __v, -1 AS __s FROM __a_0) AS d GROUP BY d.__v HAVING SUM(d.__s) <> 0) AS __verdict, (SELECT LISTAGG(CAST(__v AS VARCHAR), ', ') WITHIN GROUP (ORDER BY __v) FROM __e_0) AS __expected, (SELECT LISTAGG(CAST(__v AS VARCHAR), ', ') WITHIN GROUP (ORDER BY __v) FROM __a_0) AS __actual;
